from pydantic import BaseModel
from mcp.server.fastmcp import FastMCP
import anyio

class Inp(BaseModel):
    x:int

class Out(BaseModel):
    y:int

m=FastMCP('t')

@m.tool()
def foo(request: Inp) -> Out:
    return Out(y=request.x+1)

async def main():
    tools=await m.list_tools()
    for t in tools:
        print(t.model_dump(mode='json'))

anyio.run(main)
